INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('1', '1', '1', 'A vehicle accelerates uniformly from rest to a speed of 72 km/h in 10 seconds. What is the distance traversed in this interval?', NULL, '{\"a\":\"100 meters\",\"b\":\"200 meters\",\"c\":\"50 meters\",\"d\":\"150 meters\"}', 'a', '4.00', '1.00', 'Speed = 72 km/h = 72 × (5/18) = 20 m/s. Acceleration a = (v - u)/t = 20/10 = 2 m/s². Distance s = ut + 0.5at² = 0 + 0.5 × 2 × 100 = 100 meters.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('2', '1', '1', 'Which of the following physical quantities has the same dimensions as Planck\'s constant (h)?', NULL, '{\"a\":\"Force \\u00d7 Velocity\",\"b\":\"Angular Momentum\",\"c\":\"Linear Momentum\",\"d\":\"Energy \\u00d7 Time\\u00b2\"}', 'b', '4.00', '1.00', 'Dimensions of Planck\'s constant h = [M L² T⁻¹]. Angular momentum L = mvr = [M][L][L T⁻¹] = [M L² T⁻¹]. Thus both possess identical dimensional formulas.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('3', '1', '1', 'A body of mass 5 kg is sliding down an inclined plane of 30° at a constant velocity. What is the coefficient of kinetic friction (μk)?', NULL, '{\"a\":\"1 \\/ \\u221a3 (\\u2248 0.577)\",\"b\":\"\\u221a3 \\/ 2 (\\u2248 0.866)\",\"c\":\"0.500\",\"d\":\"1.000\"}', 'a', '4.00', '1.00', 'When a body moves down an inclined plane at constant velocity, acceleration is zero: mg sin(θ) = μk mg cos(θ). Therefore μk = tan(θ) = tan(30°) = 1/√3.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('4', '1', '1', 'In a conservative force field, the work done along any closed path is always equal to:', NULL, '{\"a\":\"Positive infinity\",\"b\":\"Dependent on the path chosen\",\"c\":\"Zero\",\"d\":\"Total mechanical energy of the system\"}', 'c', '4.00', '1.00', 'By fundamental definition, the line integral of a conservative force over any closed loop is identically zero: ∮ F · dr = 0.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('5', '1', '1', 'The escape velocity from the surface of the Earth is approximately 11.2 km/s. If a projectile is fired at 45° to the horizontal, its escape velocity will be:', NULL, '{\"a\":\"11.2 \\u00d7 sin(45\\u00b0) km\\/s\",\"b\":\"11.2 km\\/s\",\"c\":\"11.2 \\u00d7 \\u221a2 km\\/s\",\"d\":\"22.4 km\\/s\"}', 'b', '4.00', '1.00', 'Escape velocity ve = √(2GM/R) is completely independent of the projection angle. Hence it remains 11.2 km/s regardless of whether it is launched vertically or at 45°.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('6', '2', '4', 'Which cell organelle is responsible for the synthesis of steroidal hormones and lipid metabolism in animal cells?', NULL, '{\"a\":\"Rough Endoplasmic Reticulum\",\"b\":\"Smooth Endoplasmic Reticulum (SER)\",\"c\":\"Golgi Apparatus\",\"d\":\"Peroxisomes\"}', 'b', '4.00', '1.00', 'The Smooth Endoplasmic Reticulum (SER) is the major site for synthesis of lipids and steroidal hormones in animal cells.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('7', '2', '4', 'During which phase of Meiosis I does the process of crossing over (genetic recombination) occur?', NULL, '{\"a\":\"Leptotene\",\"b\":\"Zygotene\",\"c\":\"Pachytene\",\"d\":\"Diplotene\"}', 'c', '4.00', '1.00', 'Crossing over takes place at the Pachytene stage of Prophase I, mediated by the recombinase enzyme complex between non-sister chromatids.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('8', '2', '4', 'Which of the following is considered the universal electron acceptor in anaerobic glycolysis?', NULL, '{\"a\":\"Oxygen\",\"b\":\"NAD\\u207a\",\"c\":\"FAD\",\"d\":\"Cytochrome c\"}', 'b', '4.00', '1.00', 'In glycolysis, NAD⁺ acts as the oxidizing agent accepting electrons during the conversion of glyceraldehyde 3-phosphate to 1,3-bisphosphoglycerate.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('9', '2', '4', 'The functional unit of human kidney where selective reabsorption and ultrafiltration occur is called:', NULL, '{\"a\":\"Neuron\",\"b\":\"Nephron\",\"c\":\"Alveolus\",\"d\":\"Hepatic Lobule\"}', 'b', '4.00', '1.00', 'Each human kidney contains approximately one million complex tubular structures called nephrons, which are the functional filtration units.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('10', '2', '4', 'According to the competitive inhibition model, an increase in substrate concentration results in:', NULL, '{\"a\":\"Reduction of Km with constant Vmax\",\"b\":\"Overcoming the inhibitor effect, reaching normal Vmax\",\"c\":\"Permanent denaturation of enzyme\",\"d\":\"Decrease in both Vmax and Km\"}', 'b', '4.00', '1.00', 'In competitive inhibition, Vmax remains unchanged because a high concentration of substrate outcompetes the inhibitor for the active site, while Km increases.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('11', '4', '1', 'The moment of inertia of a uniform solid sphere of mass M and radius R about its diametrical axis is:', NULL, '{\"a\":\"(1\\/2) M R\\u00b2\",\"b\":\"(2\\/5) M R\\u00b2\",\"c\":\"(2\\/3) M R\\u00b2\",\"d\":\"(7\\/5) M R\\u00b2\"}', 'b', '4.00', '1.00', 'For a solid sphere about a central axis through its diameter, I = (2/5) M R². For a hollow spherical shell it is (2/3) M R².', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('12', '4', '1', 'A Carnot engine operating between 500 K and 300 K has an ideal thermodynamic efficiency of:', NULL, '{\"a\":\"40%\",\"b\":\"60%\",\"c\":\"20%\",\"d\":\"30%\"}', 'a', '4.00', '1.00', 'Efficiency η = 1 - (T_cold / T_hot) = 1 - (300 / 500) = 1 - 0.6 = 0.40, which corresponds to 40%.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('13', '5', '2', 'What is the hybridization state of the central carbon in the carbocation intermediate formed during SN1 reactions?', NULL, '{\"a\":\"sp\",\"b\":\"sp\\u00b2\",\"c\":\"sp\\u00b3\",\"d\":\"sp\\u00b3d\"}', 'b', '4.00', '1.00', 'A carbocation intermediate possesses three bonded groups and an empty p-orbital, adopting a planar geometry with sp² hybridization.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('14', '5', '2', 'Which of the following compounds will exhibit highest nucleophilic addition reactivity towards HCN?', NULL, '{\"a\":\"Formaldehyde (HCHO)\",\"b\":\"Acetaldehyde (CH\\u2083CHO)\",\"c\":\"Acetone (CH\\u2083COCH\\u2083)\",\"d\":\"Acetophenone (C\\u2086H\\u2085COCH\\u2083)\"}', 'a', '4.00', '1.00', 'HCHO has no electron donating alkyl groups and minimal steric hindrance, leaving its carbonyl carbon highly electrophilic.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('15', '8', '1', 'A ball is thrown vertically upwards with a velocity of 20 m/s. Taking g = 10 m/s², what is the maximum height attained?', NULL, '{\"a\":\"15 meters\",\"b\":\"20 meters\",\"c\":\"25 meters\",\"d\":\"30 meters\"}', 'b', '4.00', '1.00', 'Using v² = u² - 2gh. At maximum height, v = 0. Therefore h = u² / 2g = (20 × 20) / (2 × 10) = 400 / 20 = 20 meters.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('16', '8', '1', 'The SI unit of magnetic flux is:', NULL, '{\"a\":\"Tesla\",\"b\":\"Weber\",\"c\":\"Henry\",\"d\":\"Gauss\"}', 'b', '4.00', '1.00', 'Magnetic flux is measured in Weber (Wb) in the SI system. Tesla (T) is the unit of magnetic flux density (B).', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('17', '8', '1', 'Two forces of magnitude 6 N and 8 N act at a right angle (90°) to each other. What is the magnitude of their resultant force?', NULL, '{\"a\":\"14 N\",\"b\":\"10 N\",\"c\":\"2 N\",\"d\":\"7 N\"}', 'b', '4.00', '1.00', 'Resultant R = √(A² + B² + 2AB cos θ). For θ = 90°, R = √(6² + 8²) = √(36 + 64) = √100 = 10 N.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('18', '8', '1', 'Which thermodynamic process occurs at constant volume?', NULL, '{\"a\":\"Isothermal\",\"b\":\"Isobaric\",\"c\":\"Isochoric\",\"d\":\"Adiabatic\"}', 'c', '4.00', '1.00', 'An isochoric (or isometric) process is one in which the volume remains strictly constant (ΔV = 0, Work W = 0).', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('19', '8', '1', 'A convex lens of focal length 20 cm produces a real image of the same size as the object. The distance of the object from the lens is:', NULL, '{\"a\":\"10 cm\",\"b\":\"20 cm\",\"c\":\"40 cm\",\"d\":\"60 cm\"}', 'c', '4.00', '1.00', 'A convex lens forms a real, inverted image of the same size when the object is placed at 2F (twice the focal length). Here 2f = 2 × 20 = 40 cm.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('20', '9', '2', 'What is the total number of orbitals associated with the principal quantum number n = 3?', NULL, '{\"a\":\"3\",\"b\":\"6\",\"c\":\"9\",\"d\":\"18\"}', 'c', '4.00', '1.00', 'The total number of orbitals in any principal shell is given by n². For n = 3, n² = 3² = 9 (1 s-orbital, 3 p-orbitals, and 5 d-orbitals).', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('21', '9', '2', 'Which of the following molecules has a dipole moment equal to zero?', NULL, '{\"a\":\"H\\u2082O\",\"b\":\"NH\\u2083\",\"c\":\"BF\\u2083\",\"d\":\"SO\\u2082\"}', 'c', '4.00', '1.00', 'BF₃ possesses a symmetrical trigonal planar geometry (120° bond angles). The individual B-F bond dipoles cancel out symmetrically giving a net dipole moment μ = 0.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('22', '9', '2', 'The pH of a 0.001 M hydrochloric acid (HCl) solution at 25°C is:', NULL, '{\"a\":\"1\",\"b\":\"2\",\"c\":\"3\",\"d\":\"4\"}', 'c', '4.00', '1.00', 'HCl is a strong monoprotic acid. [H⁺] = 10⁻³ M. pH = -log₁₀[H⁺] = -log₁₀(10⁻³) = 3.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('23', '9', '2', 'According to Le Chatelier\'s principle, increasing the pressure in the synthesis of ammonia (N₂ + 3H₂ ⇌ 2NH₃) will:', NULL, '{\"a\":\"Shift equilibrium forward (more NH\\u2083)\",\"b\":\"Shift equilibrium backward\",\"c\":\"Have no effect on equilibrium\",\"d\":\"Decompose ammonia immediately\"}', 'a', '4.00', '1.00', 'Increasing pressure favors the direction with fewer moles of gas. Reactants = 4 moles, products = 2 moles. Thus equilibrium shifts towards products (forward).', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('24', '9', '2', 'Which element has the highest electronegativity on the Pauling scale?', NULL, '{\"a\":\"Oxygen (O)\",\"b\":\"Fluorine (F)\",\"c\":\"Chlorine (Cl)\",\"d\":\"Nitrogen (N)\"}', 'b', '4.00', '1.00', 'Fluorine is the most electronegative element with a Pauling value of 3.98 (approximately 4.0).', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('25', '11', '5', 'Which Article of the Indian Constitution is referred to as the \"Heart and Soul of the Constitution\" by Dr. B.R. Ambedkar?', NULL, '{\"a\":\"Article 14 (Equality before Law)\",\"b\":\"Article 19 (Right to Freedom)\",\"c\":\"Article 21 (Protection of Life & Liberty)\",\"d\":\"Article 32 (Right to Constitutional Remedies)\"}', 'd', '4.00', '0.50', 'Article 32 provides the right to approach the Supreme Court for enforcement of fundamental rights, termed the Heart and Soul by Dr. Ambedkar.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('26', '11', '5', 'What is the minimum age prescribed for appointment as the Governor of an Indian State?', NULL, '{\"a\":\"25 years\",\"b\":\"30 years\",\"c\":\"35 years\",\"d\":\"40 years\"}', 'c', '4.00', '0.50', 'According to Article 157, a person must be an Indian citizen and have completed the age of 35 years to be eligible for appointment as Governor.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('27', '11', '5', 'The concept of Directive Principles of State Policy (DPSP) in the Indian Constitution was borrowed from which country?', NULL, '{\"a\":\"United States of America\",\"b\":\"Ireland\",\"c\":\"United Kingdom\",\"d\":\"Canada\"}', 'b', '4.00', '0.50', 'Part IV of the Indian Constitution (DPSPs, Articles 36-51) was inspired by the Irish Constitution of 1937.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('28', '11', '5', 'Who presides over the Joint Sitting of both Houses of Parliament in India?', NULL, '{\"a\":\"President of India\",\"b\":\"Vice-President of India\",\"c\":\"Speaker of Lok Sabha\",\"d\":\"Prime Minister of India\"}', 'c', '4.00', '0.50', 'Under Article 118(4), the Speaker of Lok Sabha presides over a joint sitting of Parliament called by the President under Article 108.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('29', '11', '5', 'Under which Constitutional Amendment was the Right to Property removed from the list of Fundamental Rights?', NULL, '{\"a\":\"42nd Amendment Act, 1976\",\"b\":\"44th Amendment Act, 1978\",\"c\":\"52nd Amendment Act, 1985\",\"d\":\"73rd Amendment Act, 1992\"}', 'b', '4.00', '0.50', 'The 44th Constitutional Amendment Act of 1978 removed Right to Property from Part III and made it a legal right under Article 300A.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('30', '12', '8', 'Select the most appropriate SYNONYM of the given word: \"EPHEMERAL\"', NULL, '{\"a\":\"Eternal\",\"b\":\"Transitory\",\"c\":\"Enormous\",\"d\":\"Resilient\"}', 'b', '4.00', '0.50', 'Ephemeral means lasting for a very short time. Transitory is an exact synonym. Eternal is the antonym.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('31', '12', '8', 'Identify the segment containing a grammatical error: \"Neither of the two students / were present in the classroom / during the seminar.\"', NULL, '{\"a\":\"Neither of the two students\",\"b\":\"were present in the classroom\",\"c\":\"during the seminar\",\"d\":\"No error\"}', 'b', '4.00', '0.50', '\"Neither\" is singular when referring to individual choices. It takes a singular verb \"was present\" instead of plural \"were present\".', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('32', '12', '8', 'What is the meaning of the idiom: \"To spill the beans\"?', NULL, '{\"a\":\"To waste food carelessly\",\"b\":\"To reveal a secret prematurely\",\"c\":\"To work hard in fields\",\"d\":\"To lose temper suddenly\"}', 'b', '4.00', '0.50', '\"Spill the beans\" is an idiom that means divulging secret or confidential information without intended timing.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('33', '12', '8', 'Choose the correct ONE-WORD substitution: \"A person who renounces a religious or political belief\"', NULL, '{\"a\":\"Apostate\",\"b\":\"Agnostic\",\"c\":\"Altruist\",\"d\":\"Ascetic\"}', 'a', '4.00', '0.50', 'An apostate is someone who abandons or rejects a religious or political principle. Agnostic questions divine certainty.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('34', '12', '8', 'Fill in the blank with appropriate preposition: \"She has been suffering from fever _____ Monday last.\"', NULL, '{\"a\":\"for\",\"b\":\"since\",\"c\":\"from\",\"d\":\"by\"}', 'b', '4.00', '0.50', 'In present perfect continuous tense, \"since\" denotes a specific point in time (point of beginning), whereas \"for\" denotes a duration.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('35', '13', '4', 'Which blood vessel carries oxygenated blood from the lungs into the left atrium of the human heart?', NULL, '{\"a\":\"Pulmonary Artery\",\"b\":\"Pulmonary Vein\",\"c\":\"Coronary Sinus\",\"d\":\"Superior Vena Cava\"}', 'b', '4.00', '1.00', 'The pulmonary vein is an exception among veins; it carries freshly oxygenated blood from lungs back into the heart\'s left atrium.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('36', '13', '4', 'The functional unit of the human kidney where filtration of blood occurs is called:', NULL, '{\"a\":\"Neuron\",\"b\":\"Nephron\",\"c\":\"Alveolus\",\"d\":\"Glomerulus capsule\"}', 'b', '4.00', '1.00', 'The nephron is the structural and functional microscopic filtration unit of the kidney. Each human kidney contains ~1 million nephrons.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('37', '13', '4', 'Mendel\'s famous phenotypic dihybrid cross ratio in the F2 generation is:', NULL, '{\"a\":\"3 : 1\",\"b\":\"1 : 2 : 1\",\"c\":\"9 : 3 : 3 : 1\",\"d\":\"9 : 7\"}', 'c', '4.00', '1.00', 'In dihybrid inheritance with independent assortment, the F2 generation produces 9 round-yellow : 3 round-green : 3 wrinkled-yellow : 1 wrinkled-green.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('38', '13', '4', 'Which hormone is known as the \"Emergency Hormone\" or \"Fight-or-Flight Hormone\"?', NULL, '{\"a\":\"Insulin\",\"b\":\"Thyroxine\",\"c\":\"Adrenaline (Epinephrine)\",\"d\":\"Glucagon\"}', 'c', '4.00', '1.00', 'Adrenaline secreted by the adrenal medulla prepares the body to face stressful and emergency conditions.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('39', '13', '4', 'In DNA, adenine pairs with thymine via how many hydrogen bonds?', NULL, '{\"a\":\"1 hydrogen bond\",\"b\":\"2 hydrogen bonds\",\"c\":\"3 hydrogen bonds\",\"d\":\"Covalent peptide bond\"}', 'b', '4.00', '1.00', 'Adenine forms 2 hydrogen bonds with Thymine (A = T), while Guanine forms 3 hydrogen bonds with Cytosine (G ≡ C).', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('40', '14', '3', 'What is the product of 98 × 97 using the Vedic Maths Nikhilam (Base 100) sutra?', NULL, '{\"a\":\"9506\",\"b\":\"9406\",\"c\":\"9606\",\"d\":\"9504\"}', 'a', '4.00', '1.00', 'Base = 100. Deficiencies: -2 and -3. Left part: 98 - 3 = 95. Right part: (-2) × (-3) = 06. Result = 9506.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('41', '14', '3', 'Using the Ekadhikena Purvena rule, what is the square of 75 (75²)?', NULL, '{\"a\":\"5425\",\"b\":\"5625\",\"c\":\"5825\",\"d\":\"5725\"}', 'b', '4.00', '1.00', 'For numbers ending in 5: Left = 7 × (7 + 1) = 7 × 8 = 56. Right = 5² = 25. Together = 5625.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('42', '14', '3', 'Multiply 42 × 11 in mind using the Vedic 11-Multiplication rule:', NULL, '{\"a\":\"452\",\"b\":\"462\",\"c\":\"472\",\"d\":\"482\"}', 'b', '4.00', '1.00', 'Keep outer digits 4 and 2. Sum middle: 4 + 2 = 6. Insert between them: 462.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('43', '14', '3', 'What is 15% of 480 calculated mentally?', NULL, '{\"a\":\"68\",\"b\":\"72\",\"c\":\"76\",\"d\":\"80\"}', 'b', '4.00', '1.00', '10% of 480 = 48. 5% of 480 = half of 48 = 24. 15% = 48 + 24 = 72.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
INSERT INTO `questions` (`id`, `test_id`, `subject_id`, `question_text`, `question_image`, `options`, `correct_option`, `marks`, `negative_marks`, `explanation`, `created_at`, `updated_at`) VALUES ('44', '14', '3', 'What is the square root of 5184 (√5184)?', NULL, '{\"a\":\"68\",\"b\":\"72\",\"c\":\"78\",\"d\":\"82\"}', 'b', '4.00', '1.00', '70² = 4900, 80² = 6400. 5184 ends in 4, so unit digit is 2 or 8. Since 5184 is closer to 4900 than 6400, √5184 = 72.', '2026-11-25 10:59:09', '2026-11-25 10:59:09');
